import{_ as a,o as n,c as e,a5 as t}from"./chunks/framework.B5tqjWbr.js";const h=JSON.parse('{"title":"CT-07 奈奎斯特稳定判据 - 知识检验","description":"","frontmatter":{"date":"2026-05-19T00:00:00.000Z","section":"电机控制","chapter":"control-theory","chapterTitle":"控制理论","chapterOrder":10,"category":"控制理论","source":"motor","visibility":"public","title":"CT-07 奈奎斯特稳定判据 - 知识检验","tags":["motor-control"],"status":"learning","summary":"**模块：** CT-07 奈奎斯特稳定判据 **题目数量：** 10道 **难度分布：** ★★☆☆☆ 基础题 2道 | ★★★☆☆ 进阶题 3道 | ★★★★☆ 专业题 5道","navGroup":"控制与算法","navGroupOrder":30},"headers":[],"relativePath":"content/motor/control-theory/CT-07-assessment.md","filePath":"content/motor/control-theory/CT-07-assessment.md","lastUpdated":null}'),m={name:"content/motor/control-theory/CT-07-assessment.md"};function p(i,s,l,r,o,c){return n(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="ct-07-奈奎斯特稳定判据-知识检验" tabindex="-1">CT-07 奈奎斯特稳定判据 - 知识检验 <a class="header-anchor" href="#ct-07-奈奎斯特稳定判据-知识检验" aria-label="Permalink to &quot;CT-07 奈奎斯特稳定判据 - 知识检验&quot;">​</a></h1><p><strong>模块：</strong> CT-07 奈奎斯特稳定判据 <strong>题目数量：</strong> 10道 <strong>难度分布：</strong> ★★☆☆☆ 基础题 2道 | ★★★☆☆ 进阶题 3道 | ★★★★☆ 专业题 5道</p><hr><h2 id="一、参数计算题-★★☆☆☆" tabindex="-1">一、参数计算题（★★☆☆☆） <a class="header-anchor" href="#一、参数计算题-★★☆☆☆" aria-label="Permalink to &quot;一、参数计算题（★★☆☆☆）&quot;">​</a></h2><h3 id="题目1-nyquist判据基本应用" tabindex="-1">题目1：Nyquist判据基本应用 <a class="header-anchor" href="#题目1-nyquist判据基本应用" aria-label="Permalink to &quot;题目1：Nyquist判据基本应用&quot;">​</a></h3><p><strong>问题：</strong> 电流环开环传递函数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn><mn>0</mn><mi mathvariant="normal">/</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">L(s)=1200/s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">/</span><span class="mord mathit">s</span></span></span></span>（零极点对消后）。请：</p><ol><li>写出 Nyquist 轨迹 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>j</mi><mi>ω</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">L(j\\omega)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mclose">)</span></span></span></span> 的表达式</li><li>计算Nyquist轨迹在复平面上的位置（ω=600, 1200, 2400 rad/s 三点）</li><li>判断轨迹是否包围 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mi>j</mi><mn>0</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(-1, j0)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord">−</span><span class="mord mathrm">1</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathrm">0</span><span class="mclose">)</span></span></span></span> 点，计算闭环极点数Z</li></ol><p><strong>参考答案：</strong></p><ol><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>j</mi><mi>ω</mi><mo>)</mo><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn><mn>0</mn><mi mathvariant="normal">/</mi><mo>(</mo><mi>j</mi><mi>ω</mi><mo>)</mo><mo>=</mo><mo>−</mo><mi>j</mi><mo>(</mo><mn>1</mn><mn>2</mn><mn>0</mn><mn>0</mn><mi mathvariant="normal">/</mi><mi>ω</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">L(j\\omega) = 1200/(j\\omega) = -j(1200/\\omega)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">/</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord">−</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">/</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mclose">)</span></span></span></span></li><li>ω=600: L=-j2；ω=1200: L=-j1；ω=2400: L=-j0.5</li><li>整个轨迹在负虚轴上（从-j∞到0），不包围(-1,j0)。开环P=0→Z=N+P=0+0=0→稳定。Nyquist轨迹距(-1,j0)最近在ω=1200处：距离=|-1+j|=√2≈1.414。</li></ol><hr><h3 id="题目2-延迟裕度计算" tabindex="-1">题目2：延迟裕度计算 <a class="header-anchor" href="#题目2-延迟裕度计算" aria-label="Permalink to &quot;题目2：延迟裕度计算&quot;">​</a></h3><p><strong>问题：</strong> 电流环 ωc=1800 rad/s，实测 PM=65°。Ts=80μs（含计算+ADC延迟）。</p><ol><li>计算延迟裕度 DM（ms）</li><li>当前系统的总数字延迟约120μs。DM是否足够？</li><li>如果要将 ωc 提升到 3000 rad/s，需要将延迟降至多少？</li></ol><p><strong>参考答案：</strong></p><ol><li>DM = PM/(ωc×180/π) = 65°×(π/180)/1800 = 1.134/1800 = 0.63 ms = 630 μs</li><li>120 μs &lt;&lt; 630 μs → 裕度充足，延迟不是瓶颈。</li><li>在ωc=3000下维持相同的相对稳定性：DM_new = PM/(3000×π/180) = 1.134/3000 = 0.378 ms = 378 μs。需要数字延迟 ≤ 378 μs。当前120μs &lt; 378μs → 可行。若需更高ωc=5000: DM=1.134/5000=227μs，仍&gt;120μs。但需额外考虑滤波器等其他延迟叠加。</li></ol><hr><h2 id="二、概念辨析题-★★★☆☆" tabindex="-1">二、概念辨析题（★★★☆☆） <a class="header-anchor" href="#二、概念辨析题-★★★☆☆" aria-label="Permalink to &quot;二、概念辨析题（★★★☆☆）&quot;">​</a></h2><h3 id="题目3-nyquist图-vs-伯德图——互补关系" tabindex="-1">题目3：Nyquist图 vs 伯德图——互补关系 <a class="header-anchor" href="#题目3-nyquist图-vs-伯德图——互补关系" aria-label="Permalink to &quot;题目3：Nyquist图 vs 伯德图——互补关系&quot;">​</a></h3><p><strong>问题：</strong> 以下哪种情况伯德图可能「误判」稳定但奈奎斯特图能正确诊断？请说明原理。</p><ol><li>开环传递函数含有RHP极点（P&gt;0）</li><li>相位在高频段第二次穿越-180°且增益&gt;1</li><li>系统是条件稳定的</li></ol><p><strong>参考答案：</strong></p><ol><li>❌ 伯德图不「误判」。伯德图的Nyquist稳定判据形式（Bode稳定判据）明确要求P=0。当P&gt;0时，Bode判据需额外条件（相位穿越次数≥P/2），只是多数工程师忽略了。Nyquist判据的Z=N+P对此自动处理。</li><li>✅ 这种情伯德图容易误判。工程师通常只看第一次-180°穿越的GM。如果第二次穿越（更高频率）增益&gt;1而第一次&lt;1，伯德图仅报告安全的GM，但Nyquist图显示包围了(-1,j0)→不稳定。</li><li>✅ 条件稳定系统在增益减小时失稳——伯德图只看单一增益曲线的PM/GM，不会提示「增益降低会失稳」。Nyquist图通过分析不同增益下的包围关系揭示条件稳定。</li></ol><hr><h3 id="题目4-条件稳定的本质" tabindex="-1">题目4：条件稳定的本质 <a class="header-anchor" href="#题目4-条件稳定的本质" aria-label="Permalink to &quot;题目4：条件稳定的本质&quot;">​</a></h3><p><strong>问题：</strong> 某系统 Nyquist 图显示：在 ω1=50 rad/s 处相位=-180°, |L|=2.5（增益&gt;1）；在 ω2=500 rad/s 处相位再次=-180°, |L|=0.4（增益&lt;1）。该系统当前增益K=1。请：</p><ol><li>判断当前稳定性（P=0）</li><li>如果增益K变为0.3，稳定性如何？</li><li>如果增益K变为4，稳定性如何？</li></ol><p><strong>参考答案：</strong></p><ol><li>Nyquist轨迹在ω=ω1处穿越负实轴于点-2.5（位于-1左侧）→净包围？需跟踪全轨迹。设其他频率无额外穿越：轨迹在低频→高增益→穿越-1左侧一次→顺时针。Z=N+P。如果只有一次顺时针包围(-1,j0)且在ω1处→Z≠0→不稳定！但如果轨迹在低频更多穿越则需要完整图。简化判断：在增益&gt;1的-180°穿越中，包围关系决定稳定性。此处P=0，有两个-180°穿越点，|L|=2.5&gt;1和|L|=0.4&lt;1→净包围=1→Z=1→不稳定。</li><li>K=0.3→缩放L→ω1处|L|=0.75&lt;1, ω2处|L|=0.12&lt;1→无包围→Z=0→稳定（但这正好印证了条件稳定——增益减小使系统变稳定）。</li><li>K=4→ω1处|L|=10&gt;1, ω2处|L|=1.6&gt;1→两次包围→Z=2? N=2→Z=2→不稳定。</li></ol><hr><h2 id="三、设计应用题-★★★☆☆" tabindex="-1">三、设计应用题（★★★☆☆） <a class="header-anchor" href="#三、设计应用题-★★★☆☆" aria-label="Permalink to &quot;三、设计应用题（★★★☆☆）&quot;">​</a></h2><h3 id="题目5-延迟对nyquist图的影响——数值仿真" tabindex="-1">题目5：延迟对Nyquist图的影响——数值仿真 <a class="header-anchor" href="#题目5-延迟对nyquist图的影响——数值仿真" aria-label="Permalink to &quot;题目5：延迟对Nyquist图的影响——数值仿真&quot;">​</a></h3><p><strong>问题：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mn>2</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>⋅</mo><msup><mi>e</mi><mrow><mo>−</mo><mi>s</mi><msub><mi>T</mi><mi>s</mi></msub></mrow></msup><mi mathvariant="normal">/</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">L(s) = 2000 \\cdot e^{-sT_s} / s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8413309999999999em;"></span><span class="strut bottom" style="height:1.0913309999999998em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">⋅</span><span class="mord"><span class="mord mathit">e</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord">−</span><span class="mord mathit">s</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">s</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathrm">/</span><span class="mord mathit">s</span></span></span></span>，Ts=100μs。</p><ol><li>计算前三个相位=-180°的频率点</li><li>计算每个穿越点的|L|</li><li>判断稳定性</li></ol><p><strong>参考答案：</strong></p><ol><li>相位条件：-90° - \\omega T_s\\times180°/\\pi = -180° + k\\times360° → <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>ω</mi><msub><mi>T</mi><mi>s</mi></msub><mo>=</mo><mi>π</mi><mi mathvariant="normal">/</mi><mn>2</mn><mo>+</mo><mn>2</mn><mi>k</mi><mi>π</mi></mrow><annotation encoding="application/x-tex">\\omega T_s = \\pi/2 + 2k\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">s</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathit" style="margin-right:0.03588em;">π</span><span class="mord mathrm">/</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathit" style="margin-right:0.03148em;">k</span><span class="mord mathit" style="margin-right:0.03588em;">π</span></span></span></span> (k=0,1,2,...) k=0: ω1 = π/(2Ts) = π/(2×0.0001) = 15708 rad/s k=1: ω3 = (π/2+2π)/Ts = 78540 rad/s k=2: ω5 = (π/2+4π)/Ts = 141372 rad/s</li><li>|L(ω1)| = 2000/15708 = 0.127 &lt; 1✅；|L(ω3)| = 2000/78540 = 0.025 &lt; 1✅；|L(ω5)| = 2000/141372 = 0.014 &lt; 1✅</li><li>所有穿越点|L|&lt;1→无包围→Z=0→稳定。ωc=2000远小于临界值π/(2×0.0001)=15708，延迟安全裕度极大。</li></ol><hr><h2 id="四、综合案例题-★★★★☆" tabindex="-1">四、综合案例题（★★★★☆） <a class="header-anchor" href="#四、综合案例题-★★★★☆" aria-label="Permalink to &quot;四、综合案例题（★★★★☆）&quot;">​</a></h2><h3 id="题目6-foc电流环条件稳定诊断" tabindex="-1">题目6：FOC电流环条件稳定诊断 <a class="header-anchor" href="#题目6-foc电流环条件稳定诊断" aria-label="Permalink to &quot;题目6：FOC电流环条件稳定诊断&quot;">​</a></h3><p><strong>问题：</strong> 电流环包含：PI控制器 + RL模型(Rs=0.2Ω, Ls=3mH) + RC电流采样滤波器(τf=30μs, 即ωf=33333 rad/s)。PI参数Kp=4.5, Ki=300。系统出现小幅震荡。</p><ol><li>写出完整开环传递函数L(s)</li><li>绘制Nyquist图渐近线，找出所有-180°穿越点</li><li>判断是否为条件稳定，给出解决方案</li></ol><p><strong>参考答案：</strong></p><ol><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mo>(</mo><msub><mi>K</mi><mi>p</mi></msub><mo>+</mo><msub><mi>K</mi><mi>i</mi></msub><mi mathvariant="normal">/</mi><mi>s</mi><mo>)</mo><mo>⋅</mo><mfrac><mrow><mn>1</mn></mrow><mrow><msub><mi>R</mi><mi>s</mi></msub><mo>+</mo><msub><mi>L</mi><mi>s</mi></msub><mi>s</mi></mrow></mfrac><mo>⋅</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>τ</mi><mi>f</mi></msub><mi>s</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><msub><mi>K</mi><mi>p</mi></msub><mi>s</mi><mo>+</mo><msub><mi>K</mi><mi>i</mi></msub></mrow><mrow><mi>s</mi><mo>(</mo><msub><mi>R</mi><mi>s</mi></msub><mo>+</mo><msub><mi>L</mi><mi>s</mi></msub><mi>s</mi><mo>)</mo><mo>(</mo><mn>1</mn><mo>+</mo><msub><mi>τ</mi><mi>f</mi></msub><mi>s</mi><mo>)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">L(s) = (K_p + K_i/s) \\cdot \\frac{1}{R_s+L_s s} \\cdot \\frac{1}{1+\\tau_f s} = \\frac{K_p s + K_i}{s(R_s+L_s s)(1+\\tau_f s)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.990551em;"></span><span class="strut bottom" style="height:1.5386309999999999em;vertical-align:-0.5480799999999999em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">i</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathrm">/</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mbin">⋅</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord"><span class="mord mathit" style="margin-right:0.00773em;">R</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.00773em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">s</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">s</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">⋅</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.1132em;">τ</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.1132em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mopen">(</span><span class="mord"><span class="mord mathit" style="margin-right:0.00773em;">R</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.00773em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">s</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">s</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.1132em;">τ</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.1132em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span><span class="mclose">)</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.51222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15000000000000002em;margin-right:0.07142857142857144em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">i</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span> 代入：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><mn>4</mn><mi mathvariant="normal">.</mi><mn>5</mn><mi>s</mi><mo>+</mo><mn>3</mn><mn>0</mn><mn>0</mn></mrow><mrow><mi>s</mi><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>2</mn><mo>+</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>3</mn><mi>s</mi><mo>)</mo><mo>(</mo><mn>1</mn><mo>+</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>3</mn><mi>s</mi><mo>)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">L(s) = \\frac{4.5s + 300}{s(0.2+0.003s)(1+0.00003s)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.365108em;vertical-align:-0.52em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.34500000000000003em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">3</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">3</span><span class="mord mathit">s</span><span class="mclose">)</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></li><li>相位=分子相位-90°-arctan(Lsω/Rs)-arctan(τfω)。求解∠L(jω)=-180°：三个环节相位和=−90°。数值求解：ω≈1500 rad/s附近（PI零点转折区）→相位=arctan(4.5ω/300)-90°-arctan(0.003ω/0.2)-arctan(0.00003ω)≈−180°时|L|需数值计算。</li><li>判断：若该-180°穿越点的|L|&gt;1→不稳定。条件稳定分析：降低Kp→增加Kp是否都稳定？需要完整Nyquist分析。解决方案：提高滤波器转折频率(减小τf)，或降低ωc来确保在滤波器相位显著贡献前已达到足够的增益衰减。</li></ol><hr><h3 id="题目7-传感器噪声在nyquist图中的表现" tabindex="-1">题目7：传感器噪声在Nyquist图中的表现 <a class="header-anchor" href="#题目7-传感器噪声在nyquist图中的表现" aria-label="Permalink to &quot;题目7：传感器噪声在Nyquist图中的表现&quot;">​</a></h3><p><strong>问题：</strong> 电流传感器噪声通过反馈路径进入Nyquist分析需要考虑噪声传递函数。实际中，电流环在极高频率处（&gt;10kHz）的Nyquist轨迹受噪声影响可能呈现出随机扰动。请分析：</p><ol><li>Nyquist判据在高频噪声区域的适用性</li><li>如何在线测量Nyquist图（扫频法）并处理噪声</li></ol><p><strong>参考答案：</strong></p><ol><li>Nyquist判据基于确定性LTI模型，噪声不被建模。在极高频率（远大于ωc和fs/2），L(jω)→0, Nyquist轨迹趋近原点。噪声引入的随机扰动不会使Nyquist轨迹「包围」(-1,j0)点（因为噪声均值为零）。但强噪声下的非线性效应（如ADC饱和）可能改变有效L(jω)。对策：在Nyquist分析中关注fs/2以下的频率范围，高频噪声通过滤波抑制。</li><li>在线扫频：注入正弦扰动到Iq_ref，同步解调Iq_fb（用Lock-in Amplifier技术或Goertzel算法）→在每个频率点获得|L|和∠L。噪声处理：a) 每个频率点采集多个周期→平均降噪；b) 剔除SNR&lt;10dB的频率点；c) 相关法：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">∣</mi><mi>L</mi><mi mathvariant="normal">∣</mi><mo>=</mo><mfrac><mrow><mo>∑</mo><msub><mi>I</mi><mrow><mi>f</mi><mi>b</mi></mrow></msub><mo>⋅</mo><msub><mi>I</mi><mrow><mi>r</mi><mi>e</mi><mi>f</mi></mrow></msub></mrow><mrow><mo>∑</mo><msubsup><mi>I</mi><mrow><mi>r</mi><mi>e</mi><mi>f</mi></mrow><mn>2</mn></msubsup></mrow></mfrac></mrow><annotation encoding="application/x-tex">|L| = \\frac{\\sum I_{fb}\\cdot I_{ref}}{\\sum I_{ref}^2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.03808em;"></span><span class="strut bottom" style="height:1.7267399999999997em;vertical-align:-0.6886599999999998em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">∣</span><span class="mord mathit">L</span><span class="mord mathrm">∣</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.3735799999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="op-symbol small-op mop" style="top:0.074995em;">∑</span><span class="mord"><span class="mord mathit" style="margin-right:0.07847em;">I</span><span class="vlist"><span style="top:0.31122857142857135em;margin-left:-0.07847em;margin-right:0.07142857142857144em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord scriptscriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span></span><span style="top:-0.34480000000000005em;margin-right:0.07142857142857144em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.51308em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="op-symbol small-op mop" style="top:0.074995em;">∑</span><span class="mord"><span class="mord mathit" style="margin-right:0.07847em;">I</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.07847em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord scriptscriptstyle cramped"><span class="mord mathit" style="margin-right:0.10764em;">f</span><span class="mord mathit">b</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">⋅</span><span class="mord"><span class="mord mathit" style="margin-right:0.07847em;">I</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.07847em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord scriptscriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span>有效抑制不相关噪声。</li></ol><hr><h3 id="题目8-多轴联动耦合的mimo-nyquist分析" tabindex="-1">题目8：多轴联动耦合的MIMO Nyquist分析 <a class="header-anchor" href="#题目8-多轴联动耦合的mimo-nyquist分析" aria-label="Permalink to &quot;题目8：多轴联动耦合的MIMO Nyquist分析&quot;">​</a></h3><p><strong>问题：</strong> 两台电机驱动的XY平台，X轴运动通过机械耦合影响Y轴（耦合传递函数<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>G</mi><mrow><mi>x</mi><mi>y</mi></mrow></msub><mo>(</mo><mi>s</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">G_{xy}(s)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.036108em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">x</span><span class="mord mathit" style="margin-right:0.03588em;">y</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span></span></span></span>）。写出2×2传递函数矩阵，简述广义Nyquist判据的应用。</p><p><strong>参考答案：</strong> 传递函数矩阵：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mrow><mi mathvariant="bold">G</mi></mrow><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mrow><mo fence="true">[</mo><mtable><mtr><mtd><mrow><msub><mi>G</mi><mrow><mi>x</mi><mi>x</mi></mrow></msub><mo>(</mo><mi>s</mi><mo>)</mo></mrow></mtd><mtd><mrow><msub><mi>G</mi><mrow><mi>x</mi><mi>y</mi></mrow></msub><mo>(</mo><mi>s</mi><mo>)</mo></mrow></mtd></mtr><mtr><mtd><mrow><msub><mi>G</mi><mrow><mi>y</mi><mi>x</mi></mrow></msub><mo>(</mo><mi>s</mi><mo>)</mo></mrow></mtd><mtd><mrow><msub><mi>G</mi><mrow><mi>y</mi><mi>y</mi></mrow></msub><mo>(</mo><mi>s</mi><mo>)</mo></mrow></mtd></mtr></mtable><mo fence="true">]</mo></mrow></mrow><annotation encoding="application/x-tex">\\mathbf{G}(s) = \\begin{bmatrix} G_{xx}(s) &amp; G_{xy}(s) \\\\ G_{yx}(s) &amp; G_{yy}(s) \\end{bmatrix} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.45em;"></span><span class="strut bottom" style="height:2.40003em;vertical-align:-0.95003em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord displaystyle textstyle uncramped"><span class="mord mathbf">G</span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="minner displaystyle textstyle uncramped"><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mord"><span class="mtable"><span class="col-align-c"><span class="vlist"><span style="top:-0.6099999999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">x</span><span class="mord mathit">x</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span></span></span><span style="top:0.5900000000000003em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.03588em;">y</span><span class="mord mathit">x</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="arraycolsep" style="width:0.5em;"></span><span class="arraycolsep" style="width:0.5em;"></span><span class="col-align-c"><span class="vlist"><span style="top:-0.6099999999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">x</span><span class="mord mathit" style="margin-right:0.03588em;">y</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span></span></span><span style="top:0.5900000000000003em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.03588em;">y</span><span class="mord mathit" style="margin-right:0.03588em;">y</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size3">]</span></span></span></span></span></span></span></p><p>控制器矩阵 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mrow><mi mathvariant="bold">K</mi></mrow><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mi>d</mi><mi>i</mi><mi>a</mi><mi>g</mi><mo>(</mo><msub><mi>K</mi><mi>x</mi></msub><mo>(</mo><mi>s</mi><mo>)</mo><mo separator="true">,</mo><msub><mi>K</mi><mi>y</mi></msub><mo>(</mo><mi>s</mi><mo>)</mo><mo>)</mo></mrow><annotation encoding="application/x-tex">\\mathbf{K}(s)=diag(K_x(s), K_y(s))</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.036108em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathbf">K</span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathit">d</span><span class="mord mathit">i</span><span class="mord mathit">a</span><span class="mord mathit" style="margin-right:0.03588em;">g</span><span class="mopen">(</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">x</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.03588em;">y</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mclose">)</span></span></span></span>。</p><p>开环：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mrow><mi mathvariant="bold">L</mi></mrow><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mrow><mi mathvariant="bold">G</mi></mrow><mo>(</mo><mi>s</mi><mo>)</mo><mrow><mi mathvariant="bold">K</mi></mrow><mo>(</mo><mi>s</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">\\mathbf{L}(s)=\\mathbf{G}(s)\\mathbf{K}(s)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathbf">L</span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord textstyle uncramped"><span class="mord mathbf">G</span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mord textstyle uncramped"><span class="mord mathbf">K</span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span></span></span></span>。</p><p>广义Nyquist：计算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mrow><mi mathvariant="bold">L</mi></mrow><mo>(</mo><mi>j</mi><mi>ω</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">\\mathbf{L}(j\\omega)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathbf">L</span></span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mclose">)</span></span></span></span> 的特征值 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>λ</mi><mn>1</mn></msub><mo>(</mo><mi>j</mi><mi>ω</mi><mo>)</mo><mo separator="true">,</mo><msub><mi>λ</mi><mn>2</mn></msub><mo>(</mo><mi>j</mi><mi>ω</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">\\lambda_1(j\\omega), \\lambda_2(j\\omega)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">λ</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathrm">1</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mord"><span class="mord mathit">λ</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mclose">)</span></span></span></span> → 两条特征轨迹（Characteristic Loci）。如果两条特征轨迹的净包围(-1,j0)次数之和等于开环不稳定极点数（取负号）→ 闭环稳定。</p><p>工程简化：如果耦合<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>G</mi><mrow><mi>x</mi><mi>y</mi></mrow></msub></mrow><annotation encoding="application/x-tex">G_{xy}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.969438em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">x</span><span class="mord mathit" style="margin-right:0.03588em;">y</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>在关心的频率范围内远小于<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>G</mi><mrow><mi>x</mi><mi>x</mi></mrow></msub></mrow><annotation encoding="application/x-tex">G_{xx}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.83333em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">x</span><span class="mord mathit">x</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>（如&lt;-20dB），可近似解耦→分别对每轴进行SISO Nyquist分析。当耦合显著时（如高速高加速XY平台），必须进行MIMO分析。</p><hr><h3 id="题目9-基于nyquist的电流环带宽极限推导" tabindex="-1">题目9：基于Nyquist的电流环带宽极限推导 <a class="header-anchor" href="#题目9-基于nyquist的电流环带宽极限推导" aria-label="Permalink to &quot;题目9：基于Nyquist的电流环带宽极限推导&quot;">​</a></h3><p><strong>问题：</strong> FOC电流环受以下因素限制：a) 数字延迟Ts；b) PWM更新延迟（0.5Ts）；c) 电流采样滤波器τf。请：</p><ol><li>写出包含所有延迟和滤波器的完整L(s)</li><li>推导ωc的上限表达式（保证PM≥45°）</li></ol><p><strong>参考答案：</strong></p><ol><li><p>延迟总计≈1.5Ts（1拍计算延迟 + 0.5拍PWM更新延迟）。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><msub><mi>ω</mi><mi>c</mi></msub></mrow><mrow><mi>s</mi></mrow></mfrac><mo>⋅</mo><msup><mi>e</mi><mrow><mo>−</mo><mn>1</mn><mi mathvariant="normal">.</mi><mn>5</mn><msub><mi>T</mi><mi>s</mi></msub><mi>s</mi></mrow></msup><mo>⋅</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>τ</mi><mi>f</mi></msub><mi>s</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">L(s) = \\frac{\\omega_c}{s} \\cdot e^{-1.5T_s s} \\cdot \\frac{1}{1+\\tau_f s}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.3931879999999999em;vertical-align:-0.5480799999999999em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.4149999999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">c</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">⋅</span><span class="mord"><span class="mord mathit">e</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord">−</span><span class="mord mathrm">1</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">s</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">⋅</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.1132em;">τ</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.1132em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></p></li><li><p>相位：∠L(jωc) = -90° - 1.5Tsωc×180°/π - arctan(τfωc) 要求PM = 180° + ∠L(jωc) ≥ 45° 即 90° - 1.5Tsωc×180°/π - arctan(τfωc) ≥ 45° 1.5Tsωc×180°/π + arctan(τfωc) ≤ 45° 对于小τf，近似：1.5T_s\\omega_c \\times 180/\\pi + \\tau_f\\omega_c \\le 45° \\omega_c \\le \\frac{45°\\times\\pi/180}{1.5T_s + \\tau_f} = \\frac{0.785}{1.5T_s + \\tau_f}</p><p>数值：Ts=62.5μs, τf=8μs → ωc ≤ 0.785/(93.75+8)×10⁻⁶ = 7716 rad/s（约1228Hz）。</p></li></ol><hr><h3 id="题目10-无传感器foc中滑模观测器的nyquist稳定性验证" tabindex="-1">题目10：无传感器FOC中滑模观测器的Nyquist稳定性验证 <a class="header-anchor" href="#题目10-无传感器foc中滑模观测器的nyquist稳定性验证" aria-label="Permalink to &quot;题目10：无传感器FOC中滑模观测器的Nyquist稳定性验证&quot;">​</a></h3><p><strong>问题：</strong> 滑模观测器估计的反电动势含有高频切换分量，其等效闭环传递函数可能存在RHP极点。请设计Nyquist稳定性验证的HIL测试方案：</p><ol><li>如何从HIL仿真中提取观测器的等效开环传递函数L_obs(s)</li><li>如何判断L_obs(s)是否有RHP极点</li><li>完整验证流程</li></ol><p><strong>参考答案：</strong></p><ol><li>在HIL中注入小信号正弦扰动到观测器输入端（如注入角度误差Δθ），记录观测器输出（如估计反电动势<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mover accent="true"><mrow><mi>E</mi></mrow><mo>^</mo></mover></mrow><annotation encoding="application/x-tex">\\hat{E}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.9467699999999999em;"></span><span class="strut bottom" style="height:0.9467699999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord textstyle cramped"><span class="mord mathit" style="margin-right:0.05764em;">E</span></span></span><span style="top:-0.25233em;margin-left:0.16668em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>^</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>）。扫频获取L_{obs}(j\\omega)=Δ\\hat{E}/Δθ的频率响应数据。</li><li>判断RHP极点：a) 如果L_obs(s)的Nyquist图在ω→∞时趋于原点，且相位在高频段收敛→检查是否存在某频率段相位突变180°（共振反共振对）；b) 更可靠：拟合传递函数模型→检查极点位置。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>P</mi></mrow><annotation encoding="application/x-tex">P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.13889em;">P</span></span></span></span> = RHP极点数。</li><li>验证流程：a) 注入扫频信号→获取L_obs(jω)数据点；b) 绘制Nyquist图→统计包围(-1,j0)的圈数N；c) 从拟合模型或独立稳定性测试确定P；d) 若Z=N+P=0→观测器与被控对象构成的闭环稳定；e) HIL中实际在多种工况（不同ωe、负载）下重复验证。</li></ol>',69)])])}const y=a(m,[["render",p]]);export{h as __pageData,y as default};
